css:
/* Attract Mode: an arcade after hours. Graphite cabinets in a dark room, the page stacked in
   ruled bands across its whole width, keys with a little travel, fields sunk as wells, Figtree
   to read and Martian Mono for anything counted, and #6dff9c only where a screen is running. */
:root {
  --sans: "Figtree", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --mono: "Martian Mono", ui-monospace, Menlo, Consolas, monospace;
  --r-xl: 14px; --r-lg: 10px; --r: 8px; --r-sm: 7px;
  --band: #141e1c;
  --deck: #09100e;
  --rule: #27403f;
  --teal: #77cfce;
  --heading: #e3f0f0;
  --label: #8db7b6;
  --key-edge: #384c4c;
  --key: linear-gradient(180deg, #293938, #1c2b2a);
  --key-depth: inset 0 1px 0 rgb(255 255 255 / 0.07), 0 2px 0 #030706, 0 4px 10px -4px rgb(0 0 0 / 0.8);
  --key-down: inset 0 1px 3px rgb(0 0 0 / 0.55), 0 0 0 #030706;
  --well: inset 0 2px 4px rgb(0 0 0 / 0.55), 0 1px 0 rgb(255 255 255 / 0.05);
  --shadow: inset 0 1px 0 rgb(255 255 255 / 0.03);
  --inlay: inset 0 1px 0 rgb(255 255 255 / 0.08);
  --glow: 0 0 0 1px color-mix(in srgb, var(--green) 25%, transparent), 0 6px 22px -12px color-mix(in srgb, var(--green) 55%, transparent);
}
html { scrollbar-color: #35504d #0b1211; }
body { font: 400 1rem/1.5 var(--sans); font-kerning: normal; }
p { margin: 8px 0; }

/* Type: Figtree to read, in steps; Martian Mono, narrowed, for what is counted */
h1 { font-weight: 800; letter-spacing: -0.034em; line-height: 1.02; }
h2 { font-size: 1.5rem; font-weight: 750; letter-spacing: -0.021em; line-height: 1.2; }
h3, .eyebrow, .data caption, table.month th {
  font: 500 0.72rem/1.4 var(--mono); letter-spacing: 0.1em; text-transform: uppercase;
}
.lede { max-width: 58ch; margin-top: 12px; font-size: 1.0625rem; line-height: 1.5; color: var(--ink-2); text-wrap: pretty; }
.said-text, .description, .capture > p { text-wrap: pretty; }
.muted, .when, .meta, .rel, time { font-variant-numeric: tabular-nums; }
.icon { stroke-width: 1.5; }
nav a .icon, .section-head a .icon { stroke-width: 1.6; }

/* The frame: a column, and bands across the whole width */
main { max-width: none; padding: 0 max(1rem, calc((100% - 70rem) / 2)) 64px; overflow-x: clip; }
.in-chat main { max-width: none; padding-inline: max(1rem, calc((100% - 50rem) / 2)); }
/* Each band is ruled in its section's colour, and that colour spills faintly from the rule. */
:where(.band, .page-head, main > section.panel:not(.narrow), main > nav.panel, main > .monitors) { position: relative; isolation: isolate; }
:where(.band, main > section.panel:not(.narrow), main > nav.panel, main > .monitors)::before {
  content: ""; position: absolute; z-index: -1; inset: 0 -100vmax; pointer-events: none;
  background: linear-gradient(180deg, color-mix(in srgb, var(--accent) var(--spill, 8%), var(--tone, var(--bg))), var(--tone, var(--bg)) 120px);
  border-top: 2px solid color-mix(in srgb, var(--accent) 70%, var(--rule));
}
.band, main > section.panel:not(.narrow), main > nav.panel {
  margin: 0; padding: 32px 0 40px; background: none; border: 0; border-radius: 0; box-shadow: none;
}
.coming, [aria-labelledby="home-kids"] { --tone: var(--band); }
main > section.home-wishes.band { padding: 24px 0 32px; }
.home-wishes .section-head { margin-bottom: 12px; }
main:has(> :is(.band, section.panel, nav.panel):last-child) { padding-bottom: 0; }
/* Signing in: one cabinet, its monitor above its controls. */
.signin { margin-block: 48px; padding: 24px 24px 32px; border-color: var(--rule); }
.page-head:has(+ :is(section.panel, nav.panel, .monitors)) { margin-bottom: 0; }
.page-head + :is(section.panel, nav.panel, .monitors)::before { border-top: 0; box-shadow: none; }

.page-head { margin: 0 0 32px; padding: 32px 0 24px; align-items: flex-end; }
@media (max-width: 40rem) { .page-head { padding: 24px 0 16px; } main > .welcome { padding: 24px 0 32px; } }
.page-head::before {
  content: ""; position: absolute; z-index: -1; inset: 0 -100vmax; pointer-events: none;
  background: radial-gradient(38% 150% at 86% 0%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 70%), linear-gradient(180deg, color-mix(in srgb, var(--accent) 7%, #172624), #111a18);
  border-bottom: 2px solid color-mix(in srgb, var(--accent) 70%, var(--rule));
}
.page-head h1 { font-size: clamp(2rem, 3.6vw, 2.6rem); font-weight: 750; letter-spacing: -0.03em; color: var(--heading); }
.title-row { gap: 16px; }
/* A section's icon is a coloured key, as an arcade's buttons were. */
.title-icon, .key-icon, .section-icon, .restaurants-icon {
  display: inline-grid; place-items: center; flex: none;
  color: color-mix(in srgb, var(--accent) 88%, #fff);
  background: color-mix(in srgb, var(--accent) 22%, #162120);
  border: 1px solid color-mix(in srgb, var(--accent) 40%, #253534);
  border-radius: 10px; box-shadow: var(--inlay);
}
main h2 > svg.icon:first-child {
  box-sizing: content-box; width: 18px; height: 18px; padding: 6px; flex: none;
  color: color-mix(in srgb, var(--accent) 88%, #fff); background: color-mix(in srgb, var(--accent) 22%, #162120);
  border: 1px solid color-mix(in srgb, var(--accent) 40%, #253534); border-radius: 8px; box-shadow: var(--inlay);
}
.title-icon { width: 40px; height: 40px; }
.title-icon .icon { width: 20px; height: 20px; filter: none; }
.title-icon.presence { background: radial-gradient(circle at 50% 45%, rgb(109 255 156 / 0.1), #06110b 72%); border-color: #2b4a3c; }
.key-icon { width: 32px; height: 32px; border-radius: 8px; }
.key-icon .icon { width: 18px; height: 18px; }

/* Bands on Home and wherever a page has sections. */
.section-head { align-items: center; gap: 8px 16px; margin: 0 0 24px; }
.section-head h2, .panel > h2 { display: flex; align-items: center; gap: 12px; min-height: 34px; margin: 0; }
.panel > h2 { margin-bottom: 16px; }
.coming { --accent: var(--cyan); }
.lately { --accent: var(--lilac); }
.home-wishes { --accent: var(--pink); }
.setup { --accent: var(--amber); }
.setup, .home-todo { --spill: 6%; }
.setup ol { grid-template-columns: repeat(auto-fit, minmax(min(100%, 20rem), 1fr)); gap: 16px 32px; }
.setup li { font-size: 0.96rem; line-height: 1.45; }
.setup li::before { width: 14px; height: 14px; border-width: 1.5px; }
.setup > p { margin-top: 24px; color: var(--dim); }
.setup a:hover { color: var(--ink); }

/* Section links are small keys, their legends in the machine's face. */
.section-head a, .section-links a, .brief-more a {
  gap: 6px; min-height: 36px; padding: 0 12px;
  font: 600 0.875rem/1 var(--sans);
  color: var(--ink-2); text-decoration: none;
  background: var(--key); border: 1px solid var(--key-edge); border-radius: 7px; box-shadow: var(--key-depth);
  transition: color 0.15s, transform 0.08s, box-shadow 0.08s;
}
.section-head a:hover, .brief-more a:hover { color: var(--ink); }
.section-head a:active, .brief-more a:active { transform: translateY(2px); box-shadow: var(--key-down); }
.section-head a .icon, .brief-more .icon { width: 14px; height: 14px; color: var(--accent); }
.section-links { gap: 8px; }

/* Cabinet panels: solid, flat, one hairline, a machined corner */
.panel { padding: 24px; border-radius: 10px; box-shadow: var(--shadow); }
.panel.plain { padding: 8px 24px; }
.plain > li { padding: 16px 0; }
.card { gap: 8px; }
.card h2 { font-size: 1.125rem; font-weight: 700; letter-spacing: -0.012em; }
.card-id { font: 500 0.72rem/1 var(--mono); color: var(--label); }
.idea-card:hover, .card:has(h2 a):hover { transform: none; background: var(--surface-2); box-shadow: var(--shadow), 0 0 0 1px color-mix(in srgb, var(--accent) 45%, transparent); }
.kind { font-weight: 650; font-size: 0.84rem; letter-spacing: 0.005em; }
.kind .icon { width: 15px; height: 15px; }
.tag, .rel { font: 500 0.72rem/1.5 var(--mono); letter-spacing: 0.02em; border-radius: 5px; padding: 2px 8px; }
.rel { color: var(--ink-2); background: rgb(255 255 255 / 0.05); box-shadow: inset 0 0 0 1px var(--line-2); }
.is-today .rel { box-shadow: none; }

/* Keys: every button is a key with a little travel */
button, .button {
  min-height: 44px; padding: 0 20px; gap: 8px;
  font: 700 0.95rem/1 var(--sans); letter-spacing: 0.005em;
  color: var(--on-bright);
  background: linear-gradient(180deg, color-mix(in srgb, var(--green) 80%, #fff), var(--green) 45%, color-mix(in srgb, var(--green) 86%, #000));
  border: 1px solid color-mix(in srgb, var(--green) 55%, #000);
  border-radius: 8px;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.5), 0 3px 0 color-mix(in srgb, var(--green) 35%, #000), 0 5px 14px -6px rgb(0 0 0 / 0.9), 0 0 20px -8px color-mix(in srgb, var(--green) 55%, transparent);
}
button:hover, .button:hover { background: linear-gradient(180deg, color-mix(in srgb, var(--green-hover) 80%, #fff), var(--green-hover) 45%, color-mix(in srgb, var(--green) 90%, #000)); }
button:active, .button:active { transform: translateY(3px); box-shadow: inset 0 1px 2px rgb(0 0 0 / 0.3), 0 0 0 color-mix(in srgb, var(--green) 35%, #000), 0 0 16px -8px color-mix(in srgb, var(--green) 55%, transparent); }
.button.secondary, button.quiet, .button.ghost, .starters a, .filters button, .month-nav .button, button.mic {
  color: var(--ink-2); background: var(--key); border: 1px solid var(--key-edge); box-shadow: var(--key-depth); font-weight: 600;
}
.button.secondary:hover, button.quiet:hover, .button.ghost:hover, .starters a:hover, .filters button:hover, button.mic:hover {
  color: var(--ink); background: linear-gradient(180deg, #2f4140, #213130); border-color: #46605f; box-shadow: var(--key-depth);
}
.button.secondary:active, button.quiet:active, .button.ghost:active, .starters a:active, .filters button:active, button.mic:active { transform: translateY(2px); box-shadow: var(--key-down); }
.filters button .icon { color: var(--teal); }
.field.can-dictate > button.mic { box-shadow: none; }
button.danger { background: var(--key); border-color: color-mix(in srgb, var(--red) 45%, var(--key-edge)); box-shadow: var(--key-depth); }
.signout button.quiet, .signout button.quiet:hover, button.tick, button.tick:hover { background: none; border-color: transparent; box-shadow: none; }
button[disabled], button[disabled]:hover { background: var(--key); color: var(--dim); border-color: var(--key-edge); box-shadow: none; opacity: 0.6; }
/* The mic is a round arcade button, dished. */
button.mic { border-radius: 50%; background: radial-gradient(circle at 50% 38%, #2b3c3b, #172322 70%); }

/* Wells: every box you type in is sunk into the panel */
input[type="text"], input[type="password"], input[type="search"], input[type="url"], input[type="date"],
input[type="time"], input[type="datetime-local"], input:not([type]), textarea, select {
  min-height: 44px; padding: 10px 12px; font: 400 1rem/1.4 var(--sans);
  background-color: var(--field); border: 1px solid color-mix(in srgb, var(--edge) 75%, var(--field));
  border-top-color: color-mix(in srgb, var(--edge) 45%, #000); border-radius: 7px; box-shadow: var(--well);
}
select { padding-right: 40px; background-position: right 12px center; }
input:focus, textarea:focus, select:focus { box-shadow: var(--well), 0 0 0 3px color-mix(in srgb, var(--lit) 16%, transparent); }
label { font-size: 0.875rem; font-weight: 600; letter-spacing: 0.005em; color: var(--ink-2); margin-bottom: 8px; }
input[type="checkbox"], input[type="radio"] {
  appearance: none; display: inline-grid; place-items: center; flex: none;
  width: 20px; height: 20px; margin: 0 10px 0 0; vertical-align: -0.28em;
  background: var(--field); border: 1px solid var(--edge); border-radius: 5px; box-shadow: var(--well); cursor: pointer;
}
input[type="radio"] { border-radius: 50%; }
input[type="checkbox"]::before { content: ""; width: 5px; height: 10px; margin-top: -2px; border: solid var(--on-bright); border-width: 0 2px 2px 0; transform: rotate(45deg) scale(0); transition: transform 0.12s; }
input[type="radio"]::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--on-bright); transform: scale(0); transition: transform 0.12s; }
input:is([type="checkbox"], [type="radio"]):checked { background: var(--lit); border-color: var(--lit); box-shadow: 0 0 12px -3px color-mix(in srgb, var(--lit) 70%, transparent); }
input:is([type="checkbox"], [type="radio"]):checked::before { transform: rotate(45deg) scale(1); }
input[type="radio"]:checked::before { transform: scale(1); }
input:is([type="checkbox"], [type="radio"]):focus-visible { outline: 2px solid var(--green); outline-offset: 2px; }
.form fieldset, #google fieldset { border-color: var(--line-2); border-radius: 8px; }

/* The bar: the arcade's dark ceiling, the places along it as keys */
.bar { border-bottom: 1px solid #1f302e; box-shadow: 0 1px 0 rgb(0 0 0 / 0.6); }
.brand-name { font: 600 1rem/1 var(--mono); letter-spacing: -0.02em; }
.brand-mark { border-radius: 9px; }
nav a, .menu > summary { font: 600 0.94rem/1 var(--sans); letter-spacing: 0.003em; border-radius: 7px; }
@media (min-width: 52rem) {
  .places { gap: 4px; }
  .places a { padding: 0 14px; min-height: 38px; }
  .places a[aria-current="page"], .tools > a[aria-current="page"], .menu.here > summary {
    background: #0a1110; box-shadow: inset 0 2px 3px rgb(0 0 0 / 0.7), inset 0 0 0 1px #213331;
  }
  .places a:hover, .tools > a:hover, .menu > summary:hover { background: var(--surface-2); }
}
.menu-list { border-color: var(--rule); border-radius: 10px; background: var(--surface); }
.places a[aria-current="page"] .icon, nav a[aria-current="page"] .icon { filter: none; }

/* Home: the greeting is the marquee */
.welcome {
  overflow: visible; margin: 0; padding: 40px 0 48px; gap: 32px 48px;
  background: none; border: 0; border-radius: 0; box-shadow: none;
}
.welcome::before {
  inset: 0 -100vmax; z-index: -1; -webkit-mask-image: none; mask-image: none; border-top: 0; box-shadow: none; border-bottom: 1px solid var(--rule);
  background:
    radial-gradient(38% 80% at 76% 45%, rgb(109 255 156 / 0.06), transparent 70%),
    radial-gradient(40% 90% at 100% 0%, rgb(119 207 206 / 0.08), transparent 70%),
    linear-gradient(180deg, #152321, #0f1816);
}
@media (min-width: 64rem) { .welcome { grid-template-columns: minmax(0, 1.4fr) minmax(24rem, 1fr); } .welcome .next-up { align-self: start; margin-top: 50px; } }
@media (min-width: 40rem) { .on-radar .radar { width: 10rem; } }
.speaker { gap: 8px 12px; margin-bottom: 16px; }
.speaker strong { font-size: 1.05rem; font-weight: 750; letter-spacing: -0.01em; }
.speaker .eyebrow { color: var(--label); }
/* The ask is a sunk control deck. */
.ask, .welcome .ask { background: var(--deck); border: 1px solid #22302f; border-top-color: #050908; border-radius: 12px; box-shadow: inset 0 3px 8px rgb(0 0 0 / 0.6), 0 1px 0 rgb(255 255 255 / 0.05); padding: 8px 8px 12px; }
.ask textarea, .ask textarea:focus { box-shadow: none; background: transparent; border: 0; }
.ask:focus-within, .welcome .ask:focus-within { border-color: color-mix(in srgb, var(--lit) 70%, #000); box-shadow: inset 0 3px 8px rgb(0 0 0 / 0.6), 0 0 0 3px color-mix(in srgb, var(--lit) 14%, transparent), 0 0 28px -10px color-mix(in srgb, var(--green) 45%, transparent); }
.ask-question { padding: 12px 12px 0; font-size: clamp(1.5rem, 2.6vw, 1.9rem); font-weight: 800; line-height: 1.12; letter-spacing: -0.03em; }
.ask-question label { color: var(--heading); font-weight: 800; }
.ask-bar { gap: 8px 16px; padding: 8px 8px 0 12px; }
.ask .who label, .ask .who .from { font: 500 0.72rem/1 var(--mono); letter-spacing: 0.1em; text-transform: uppercase; color: var(--label); }
.ask .who select { min-height: 40px; background-color: #0d1615; border-color: #2b3d3c; }
.ask .locate label { font-size: 0.9rem; color: var(--ink-2); }
.ask .locate .icon { color: var(--teal); }
.starters { gap: 8px; margin-top: 16px; }
@media (max-width: 30rem) {
  .ask { padding: 6px 6px 10px; }
  .ask-bar { gap: 8px; padding: 8px 4px 0 6px; }
  .ask .who { gap: 6px; }
  .ask .who select { padding-right: 32px; background-position: right 8px center; }
}
.starters a { min-height: 40px; padding: 0 16px; border-radius: 8px; font-size: 0.9rem; color: var(--ink-2); }
.thread.brief { margin-top: 24px; }
.brief-more { margin: 12px 0 0 48px; }
.next-up .next-label, .on-radar-label { letter-spacing: 0.08em; }

/* The monitors: a line of light passes down the glass as each switches on. */
.crt { border-radius: 18px; }
.crt-tube { border-radius: 12px / 14px; }
.crt::before {
  content: ""; position: absolute; z-index: 6; left: 0.9rem; right: 0.9rem; top: 0.7rem; height: 2px; pointer-events: none;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--phosphor) 60%, #fff) 20% 80%, transparent);
  box-shadow: 0 0 14px 3px color-mix(in srgb, var(--phosphor) 40%, transparent), 0 -18px 24px -6px color-mix(in srgb, var(--phosphor) 12%, transparent);
  opacity: 0; animation: scan 1.25s cubic-bezier(0.45, 0, 0.55, 1) 0.15s 1 both;
}
@keyframes scan { 0% { top: 0.7rem; opacity: 0; } 8% { opacity: 1; } 80% { opacity: 0.7; } 100% { top: calc(100% - 1.7rem); opacity: 0; } }

/* Coming up: each plan a ticket, its day on a key. */
.tickets { display: grid; gap: 16px; grid-template-columns: repeat(auto-fill, minmax(min(100%, 15.5rem), 1fr)); }
.tickets > li, .tickets > li:first-child, .tickets > li:last-child {
  grid-template-columns: auto minmax(0, 1fr); align-items: start; gap: 16px;
  padding: 16px; background: var(--surface); border: 1px solid var(--rule); border-radius: 10px; box-shadow: var(--shadow);
}
.tickets > li.empty { grid-column: 1 / -1; }
.tickets .agenda-body, .tickets .when { display: flex; flex-direction: column; align-items: flex-start; }
.tickets .agenda-body { align-self: stretch; }
.tickets .when { flex: 1; }
.tickets .rel { margin-top: auto; }
.agenda .what { font-size: 1.02rem; font-weight: 700; letter-spacing: -0.008em; line-height: 1.3; }
.agenda .when { gap: 8px; margin-top: 6px; font-size: 0.875rem; }
.chip {
  width: 56px; padding: 7px 0 8px; gap: 0;
  background: linear-gradient(180deg, color-mix(in srgb, var(--cyan) 14%, #243231), color-mix(in srgb, var(--cyan) 7%, #182322));
  border: 1px solid color-mix(in srgb, var(--cyan) 26%, #2a3a39); border-radius: 8px; box-shadow: var(--inlay);
}
.chip-mon, .chip-dow { font: 500 0.72rem/1.1 var(--mono); letter-spacing: 0.08em; text-transform: uppercase; }
.chip-mon { color: var(--cyan); }
.chip-day { margin: 3px 0 2px; font-size: 1.5rem; font-weight: 800; letter-spacing: -0.03em; line-height: 1; }
.chip-dow { color: var(--label); }
.chip.is-today { border-color: color-mix(in srgb, var(--amber) 60%, var(--key-edge)); box-shadow: var(--inlay), 0 0 16px -6px color-mix(in srgb, var(--amber) 60%, transparent); }

/* To do: rows, two to a line where there is room. */
.home-todo { --accent: var(--lemon); }
.checklist { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 26rem), 1fr)); column-gap: 48px; border-bottom: 1px solid var(--line); }
.checklist > li, .checklist > li:first-child, .checklist > li:last-child { padding: 12px 0; border-top: 1px solid var(--line); border-bottom: 0; gap: 12px; }
.checklist .what { font-size: 1rem; font-weight: 650; }
.checklist .when { font-size: 0.86rem; }
button.tick::before { width: 22px; height: 22px; border: 1px solid var(--edge); border-radius: 6px; background: var(--field); box-shadow: var(--well); }
.task-box { border-width: 1px; border-radius: 6px; background: var(--field); box-shadow: var(--well); }
.task-done .task-box { background: var(--lit); border-color: var(--lit); }

/* Lately added: four cabinets in a row, and the way to something to eat under them. */
.idea-cards { gap: 16px; grid-template-columns: repeat(auto-fill, minmax(min(100%, 15rem), 1fr)); margin-bottom: 16px; }
.idea-card { gap: 6px; padding: 16px 16px 20px; border-color: var(--rule); }
/* Each idea a cabinet, its kind's colour along its top like a marquee. */
.idea-card, .cards > .card { border-top: 3px solid color-mix(in srgb, var(--accent) 62%, var(--rule)); }
.idea-card strong { font-size: 1.05rem; font-weight: 700; letter-spacing: -0.01em; }
.idea-card .muted { font-size: 0.875rem; }
.restaurants-link { gap: 16px; padding: 16px 20px; background: var(--surface); border-color: var(--rule); }
.restaurants-link:hover { border-color: color-mix(in srgb, var(--amber) 50%, var(--rule)); box-shadow: none; }
.restaurants-icon { width: 44px; height: 44px; }
.restaurants-link .eyebrow { color: var(--amber); }
.restaurants-link strong { font-size: 1.1rem; font-weight: 750; letter-spacing: -0.012em; }
.home-wishes ul.plain > li { padding: 12px 0; }
.home-wishes ul.plain { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 16rem), 1fr)); column-gap: 48px; }
.home-wishes ul.plain > li, .home-wishes ul.plain > li:first-child, .home-wishes ul.plain > li:last-child { border-top: 1px solid var(--line); border-bottom: 0; padding: 12px 0; }
.home-wishes li strong { font-weight: 700; }

/* Chat */
.thread { gap: 20px; }
.bubble { padding: 12px 16px 14px; border-radius: 12px; }
.said-bot .bubble { border-bottom-left-radius: 3px; }
.said-them .bubble { border-bottom-right-radius: 3px; border-color: #343f45; }
.said-by { gap: 4px 10px; margin-bottom: 6px; font: 500 0.72rem/1.3 var(--mono); letter-spacing: 0.06em; text-transform: uppercase; }
.said-by strong { font: 700 0.875rem/1 var(--sans); letter-spacing: 0; text-transform: none; color: var(--ink); }
.said-text { line-height: 1.5; max-width: 62ch; }
.avatar { border-radius: 8px; font-weight: 800; }
.said-them .avatar { box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.3); }
.did { font: 0.72rem/1.4 var(--mono); }

/* Ideas and the other lists */
.tabs { gap: 8px; padding: 0 0 3px; background: none; border: 0; }
.tabs a { padding: 0 16px; min-height: 40px; border-radius: 8px; font-weight: 600; color: var(--ink-2); background: var(--key); border: 1px solid var(--key-edge); box-shadow: var(--key-depth); }
.tabs a[aria-current="page"], .settings-nav a[aria-current="page"] { color: var(--ink); background: var(--deck); border-color: #22302f; box-shadow: var(--key-down); transform: translateY(2px); }
.filters { gap: 16px; padding: 20px 24px 24px; background: var(--band); border-color: var(--rule); }
.count { font: 600 0.875rem/1.4 var(--sans); font-variant-numeric: tabular-nums; color: var(--label); margin: 24px 0 16px; }
.cards { gap: 16px; }
.meta { gap: 6px 16px; font-size: 0.86rem; }
.meta .icon { width: 14px; height: 14px; }
.capture > summary, .panel > summary { font-weight: 700; }

/* Status: sections are bands; three monitors side by side, ruled rather than boxed */
main > .monitors { gap: 0; margin: 0; padding: 32px 0 40px; }
main > .monitors > .panel { margin: 0; padding: 0 32px; background: none; border: 0; border-left: 1px solid var(--line); border-radius: 0; box-shadow: none; }
main > .monitors > .panel:first-child { border-left: 0; padding-left: 0; }
@media (max-width: 60rem) { main > .monitors > .panel { border-left: 0; padding: 0 0 24px; } }
.lights > li { gap: 12px; }
.light { width: 9px; height: 9px; margin-top: 7px; }
.light.on { background: var(--green); box-shadow: 0 0 8px color-mix(in srgb, var(--green) 70%, transparent); }
.data th { font: 500 0.72rem/1.3 var(--mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--label); }
.data .num, .share-cell, .hours td { font-family: var(--mono); font-size: 0.8rem; }
.section-card:hover { border-color: color-mix(in srgb, var(--teal) 45%, var(--rule)); }
table.month td { height: 6rem; border-color: var(--line); }
.event { border-radius: 4px; }

/* The foot: one more band */
.foot { max-width: none; padding: 32px max(1rem, calc((100% - 70rem) / 2)) 40px; background: #0b1211; border-top: 1px solid var(--rule); box-shadow: 0 -1px 0 rgb(0 0 0 / 0.5); }
.foot-mark { font: 600 0.9rem/1 var(--mono); }
.foot .legal { font: 0.72rem/1.6 var(--mono); }

/* The machine's face, narrowed: after every shorthand that would reset it. */
:is(.eyebrow, h3, .data caption, table.month th, .said-by, .tag, .rel, .card-id, .chip-mon, .chip-dow,
  .brand-name, .foot-mark, .foot .legal, .ask .who label, .ask .who .from,
  .data th, .data .num, .share-cell, .hours td, .did, .meta .cost, .event small) { font-stretch: 80%; }
